// Hareket alarmı: PIR hareket görünce buzzer öter, LED yanar.
const int PIR_PIN = 2;
const int LED_PIN = 9;
const int BUZZER_PIN = 7;

void setup() {
  Serial.begin(9600);
  pinMode(PIR_PIN, INPUT);
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  Serial.println("Hazir. Gercek PIR icin 30 saniye isinma gerekir.");
}

void loop() {
  if (digitalRead(PIR_PIN) == HIGH) {
    Serial.println("Hareket var!");
    digitalWrite(LED_PIN, HIGH);
    for (int i = 0; i < 3; i++) {
      tone(BUZZER_PIN, 2000, 150);
      delay(300);
    }
  } else {
    digitalWrite(LED_PIN, LOW);
  }
  delay(100);
}
